start=5617
head="רשומה 3 · 23.11.2026, 11:28 · משמרת חצות היום"
paras=[
("מה נעשה. ","מודל האפס שתוכנן ברשומה 2. כל הקטגוריות של כל המאמרים (1,999,486 מאמרים, אחרי איחוד כינויים) עורבבו באקראי בין המאמרים, כך שכל מאמר שומר על מספר הקטגוריות שלו וכל קטגוריה שומרת על השכיחות שלה. על הנתונים האמיתיים ועל 5 עירובים (זרעים 100–104) הורץ אותו חישוב: משולש = שלוש קטגוריות שכל זוג מהן חולק לפחות 300 מאמרים; יחס = מאמרים בשלושתן חלקי ההערכה בהנחת אי-תלות; נספרים רק משולשים שבהם ההערכה 5 ומעלה; חלול = יחס מתחת ל-0.15. (כפילויות שנוצרו בתוך מאמר בעירוב אוחדו; זה משפיע על מעט מאוד מאמרים.)"),
("ממצאים (חישוב). ","נתונים אמיתיים: 1,730 משולשים, מתוכם 18 חלולים, ו-17 מהם עם הערכה של 20 מאמרים ומעלה (המרבית 211). חציון היחס 1.29: מאמרים אמיתיים נוטים להתקבץ ביותר משמצפה אי-תלות."),
("","מודל האפס (5 עירובים): כ-10,000 משולשים בכל עירוב, ומספר החלולים בין 4 ל-14. אבל כולם עם הערכה קטנה: הגבוהה ביותר בכל העירובים היא 12.2. חלולים עם הערכה של 20 ומעלה: 0 בכל חמשת העירובים, מול 17 בנתונים האמיתיים. חציון היחס 1.00, כצפוי ממודל שבנוי על אי-תלות."),
("המסקנה. ","החורים הגדולים אמיתיים: עירוב אקראי לא מייצר משולש חלול שבו היו צפויים 20 מאמרים או יותר, ובנתונים יש 17 כאלה. החריג היחיד הוא המשולש מכשור אסטרונומי + פיזיקה חישובית + אופטיקה (0 מאמרים מול 6.7 צפויים). ההערכה שלו קטנה כמו של החלולים שהעירוב יצר במקרה, ולכן אין להסתמך עליו. שני החלולים העקשנים מרשומה 2 עברו את המבחן: מכניקה סטטיסטית + ביופיזיקה + קוונטים (19 מאמרים מול 211 צפויים) ואנליזה מרוכבת + גאומטריה דיפרנציאלית + הסתברות (6 מול 70)."),
("חלולים חדשים ברשימה. ","כשמשתמשים בכל השנים יחד ובכלל ה-0.15 מופיעים גם: אנליזה מרוכבת + מערכות דינמיות + אנליזה פונקציונלית (10 מול 111); מכניקה סטטיסטית + אלקטרונים מתואמים + כימיה פיזיקלית (10 מול 111); אנליזה מרוכבת + גאומטריה דיפרנציאלית + אנליזה פונקציונלית (18 מול 175); מחשבים וחברה + למידת מכונה + פיזיקה חברתית (17 מול 119). אנליזה מרוכבת מופיעה בשלושה חורים, מכניקה סטטיסטית בארבעה."),
("מה לא אומת. ","מודל האפס חלש: הוא הורס גם את מבנה הזוגות, ולכן הוא בודק בעיקר שהנוסחה \"צפוי\" אינה מייצרת חורים מעצמה. הוא לא בודק אם החור צפוי בהינתן מבנה הזוגות האמיתי. מודל חזק יותר ישמור גם על ספירת הזוגות. ייתכן שחלק מהחורים נובעים ממנהגי רישום ב-arXiv (למשל, הגבלה מעשית על מספר הקטגוריות שמאמר מקבל), ולא מפער בידע עצמו. עדיין עד 2021 בלבד, ו-OpenAlex עדיין חסום."),
("הצעד הבא. ","לקרוא את הכותרות והתקצירים של המאמרים המעטים שכן יושבים בשני החורים העקשנים (19 ו-6 מאמרים, מתוך מאגר ה-HF שכולל תקצירים), ולנסח לכל חור שאלה מחקרית אחת שיושבת בדיוק בתוכו. אם יישאר זמן: לבדוק אם חורים נובעים ממגבלת מספר הקטגוריות, על ידי השוואה למשולשים שבהם כל המאמרים בעלי 3 קטגוריות לפחות."),
]
text="\n"+head
rng=[]; idx=start+1+len(head)
heading_range=(start+1,start+1+len(head))
for lab,body in paras:
    s=idx+1; text+="\n"+lab+body
    rng.append((s,s+len(lab),s+len(lab)+len(body)))
    idx=s+len(lab)+len(body)
assert all(ord(c)<0x10000 for c in text)
req=[{"insertText":{"location":{"index":start},"text":text}},
 {"updateParagraphStyle":{"range":{"startIndex":heading_range[0],"endIndex":heading_range[1]},"paragraphStyle":{"namedStyleType":"HEADING_3","direction":"RIGHT_TO_LEFT"},"fields":"namedStyleType,direction"}},
 {"updateParagraphStyle":{"range":{"startIndex":rng[0][0],"endIndex":rng[-1][2]},"paragraphStyle":{"namedStyleType":"NORMAL_TEXT","direction":"RIGHT_TO_LEFT"},"fields":"namedStyleType,direction"}},
 {"updateTextStyle":{"range":{"startIndex":rng[0][0],"endIndex":rng[-1][2]},"textStyle":{"bold":False},"fields":"bold"}},
 {"updateTextStyle":{"range":{"startIndex":heading_range[0],"endIndex":heading_range[1]},"textStyle":{"bold":True},"fields":"bold"}}]
for s,m,e in rng:
    if m>s: req.append({"updateTextStyle":{"range":{"startIndex":s,"endIndex":m},"textStyle":{"bold":True},"fields":"bold"}})
json.dump(req,open("append3.json","w"),ensure_ascii=False)
print(len(req))
